$(document).ready(function(){ 
if (sforce.console.isInConsole()){ 
var CMWindow = sforce.console.openPrimaryTab(undefined, '/setup/ui/recordtypeselect.jsp?ent=Opportunity&retURL=%2F006%2Fo&save_new_url=%2F006%2Fe%3FretURL%3D%252F006%252Fo%26accid%3D{!Account.Id}', true); 
} 
else{ 
if({!Account.Customer_Service_Issue__c} > 0) { 
alert ("You cannot create a new Opportunity for this Account right now, there is a customer service issue"); 
} 
else{ 
window.open('/setup/ui/recordtypeselect.jsp?ent=Opportunity&retURL=%2F{!Account.Id}&save_new_url=%2F006%2Fe%3FretURL%3D%252F{!Account.Id}%26accid%3D{!Account.Id}'); 
} 
} 
});


